from pathlib import Path
import subprocess,os,pwd,json
root=Path('/srv/projects/lowcost-europa')
venv=root/'.venv'
old=b'/srv/lowcost-europa/.venv/'
new=b'/srv/projects/lowcost-europa/.venv/'
def command(args,timeout=15):
 return subprocess.run(args,capture_output=True,text=True,timeout=timeout)
def active(name):
 return command(['systemctl','is-active',name+'.service'],9).stdout.strip()
def bots():
 p=command(['pm2','jlist'],14)
 if p.returncode:raise RuntimeError('PM2 inaccessible')
 return {x.get('name'):(x.get('pm2_env') or {}).get('status') for x in json.loads(p.stdout) if x.get('name') in ('iptvpn_bot','telegram-robot-leads')}
services=['lowcost-europa','fadego-staging','pink-iptv-backend','pink-vpn','pm2-root','nginx','postgresql@16-main']
baseline={n:active(n) for n in services}
if any(x!='active' for x in baseline.values()):raise RuntimeError('Service preflight failed')
if any(bots().get(n)!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Bot offline')
if not root.is_dir() or root.is_symlink() or not venv.is_dir():raise RuntimeError('LowCost canonical project missing')
owner=pwd.getpwuid(root.stat().st_uid).pw_name
def git(*args):
 return command(['sudo','-n','-u',owner,'git','-C',str(root),*args],15)
status0=git('status','--porcelain','--untracked-files=no')
if status0.returncode:raise RuntimeError('LowCost Git state unavailable as owner')
updates={}
for f in (venv/'bin').iterdir():
 if not f.is_file() or f.is_symlink() or f.stat().st_size>150000:continue
 with f.open('rb') as x:header=x.readline()
 if header.startswith(b'#!') and old in header:updates[f]=f.read_bytes()
if not updates or not any(p.name=='gunicorn' for p in updates):raise RuntimeError('Original Python launcher paths not found')
cfg=venv/'pyvenv.cfg'
cfgold=cfg.read_bytes() if cfg.is_file() else None
try:
 for p,blob in updates.items():
  pos=blob.find(b'\n')
  if pos<0:raise RuntimeError('Python script header not terminated')
  edited=blob[:pos].replace(old,new)+blob[pos:]
  if edited==blob:raise RuntimeError('Header replacement not applied')
  p.write_bytes(edited)
 if cfgold and old in cfgold:cfg.write_bytes(cfgold.replace(old,new))
 for name in ['gunicorn','pip']:
  p=command([str(venv/'bin'/name),'--version'],17)
  if p.returncode:raise RuntimeError('New Python launcher failed: '+name+' '+p.stderr[:180])
 for p in updates:
  with p.open('rb') as f:
   head=f.readline()
   if old in head or new not in head:raise RuntimeError('Unexpected shebang after update')
 status1=git('status','--porcelain','--untracked-files=no')
 if status1.returncode or status1.stdout!=status0.stdout:raise RuntimeError('Tracked application changed')
 if any(active(n)!=s for n,s in baseline.items()):raise RuntimeError('Systemd state changed')
 if any(bots().get(n)!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Telegram bot state changed')
except Exception:
 for p,blob in updates.items():p.write_bytes(blob)
 if cfgold is not None:cfg.write_bytes(cfgold)
 print('LOWCOST_VENV_ROLLBACK=APPLIED')
 raise
print('CANONICAL_LOWCOST_VENV='+str(venv))
print('OLD_SHEBANGS_FIXED='+str(len(updates)))
print('FIXED_COMMANDS='+','.join(sorted(p.name for p in updates)))
print('GUNICORN_AND_PIP_EXECUTABLE=PASS')
print('GIT_TRACKED_STATE_UNCHANGED=YES')
print('SYSTEMD_SERVICES_AND_BOTS_UNCHANGED=YES')
print('LOWCOST_PYTHON_RUNTIME_FIX=PASS')
PY
